using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A loop that stops after its first item, in Go, Rust, Dart, PHP, Perl, Scala, PowerShell, Ruby, Lua and Fortran: an if that
/// returns when the item matches and an else that returns when it does not. The change takes the else out where the line
/// after the loop already gives back the same, and puts its return after the loop where the loop ends its function; where
/// other code follows the loop, or the loop is inside another, there is none. Left alone in each: an else giving back the
/// item itself, an if whose return is inside a further if, and an else-if chain that skips some items before deciding -
/// and PowerShell's ForEach-Object, whose return goes on to the next item.
/// </summary>
public class ReturnInLoopTests
{
    private static SourceFile Source(string fileName, string code) =>
        new() { Path = Path.Combine(Path.GetTempPath(), fileName), Lines = code.Replace("\r\n", "\n").Split('\n') };

    private static IReadOnlyList<LogicFinding> Scanned(string fileName, string code) =>
        LogicPatterns.Scan(Source(fileName, code))
            .Where(finding => finding.PatternId.EndsWith("-return-in-loop", StringComparison.Ordinal))
            .ToList();

    /// <summary>The file, the program, and what the check said of it here: the finding's line, check and words.</summary>
    public static TheoryData<string, string, string> Found => new()
    {
        { "search.dart", "bool contains(List<int> items, int wanted) {\n  for (var item in items) {\n    if (item == wanted) {\n      return true;\n    } else {\n      return false;\n    }\n  }\n  return false;\n}\n\nvoid main() {\n  print(contains([3, 5, 7], 7));\n}\n", "5|logic-dart-return-in-loop|the loop returns on its first pass whichever way the `if` goes, so it never looks past the first item" },
        { "search.f90", "program main\n  implicit none\n  print *, has_item([3, 5, 7], 7)\ncontains\n  logical function has_item(items, wanted)\n    integer, intent(in) :: items(:), wanted\n    integer :: index\n    do index = 1, size(items)\n      if (items(index) == wanted) then\n        has_item = .true.\n        return\n      else\n        has_item = .false.\n        return\n      end if\n    end do\n    has_item = .false.\n  end function has_item\nend program main\n", "12|logic-fortran-return-in-loop|the loop returns on its first pass whichever way the `if` goes, so it never looks past the first item" },
        { "search.go", "package main\n\nimport \"fmt\"\n\nfunc contains(items []int, wanted int) bool {\n\tfor _, item := range items {\n\t\tif item == wanted {\n\t\t\treturn true\n\t\t} else {\n\t\t\treturn false\n\t\t}\n\t}\n\treturn false\n}\n\nfunc main() {\n\tfmt.Println(contains([]int{3, 5, 7}, 7))\n}\n", "9|logic-go-return-in-loop|the loop returns on its first pass whichever way the `if` goes, so it never looks past the first item" },
        { "search.lua", "local function contains(items, wanted)\n  for _, item in ipairs(items) do\n    if item == wanted then\n      return true\n    else\n      return false\n    end\n  end\n  return false\nend\n\nprint(contains({3, 5, 7}, 7))\n", "5|logic-lua-return-in-loop|the loop returns on its first pass whichever way the `if` goes, so it never looks past the first item" },
        { "search.php", "<?php\nfunction contains(array $items, int $wanted): bool\n{\n    foreach ($items as $item) {\n        if ($item === $wanted) {\n            return true;\n        } else {\n            return false;\n        }\n    }\n    return false;\n}\n\nvar_dump(contains([3, 5, 7], 7));\n", "7|logic-php-return-in-loop|the loop returns on its first pass whichever way the `if` goes, so it never looks past the first item" },
        { "search.pl", "use strict;\nuse warnings;\n\nsub contains {\n    my ($wanted, @items) = @_;\n    foreach my $item (@items) {\n        if ($item == $wanted) {\n            return 1;\n        } else {\n            return 0;\n        }\n    }\n    return 0;\n}\n\nprint contains(7, 3, 5, 7), \"\\n\";\n", "9|logic-perl-return-in-loop|the loop returns on its first pass whichever way the `if` goes, so it never looks past the first item" },
        { "search.ps1", "function Test-Contains($items, $wanted) {\n    foreach ($item in $items) {\n        if ($item -eq $wanted) {\n            return $true\n        } else {\n            return $false\n        }\n    }\n    return $false\n}\n\nTest-Contains @(3, 5, 7) 7\n", "5|logic-powershell-return-in-loop|the loop returns on its first pass whichever way the `if` goes, so it never looks past the first item" },
        { "search.rb", "def contains(items, wanted)\n  items.each do |item|\n    if item == wanted\n      return true\n    else\n      return false\n    end\n  end\n  false\nend\n\nputs contains([3, 5, 7], 7)\n", "5|logic-ruby-return-in-loop|the loop returns on its first pass whichever way the `if` goes, so it never looks past the first item" },
        { "search.rs", "fn contains(items: &[i32], wanted: i32) -> bool {\n    for item in items {\n        if *item == wanted {\n            return true;\n        } else {\n            return false;\n        }\n    }\n    false\n}\n\nfn main() {\n    println!(\"{}\", contains(&[3, 5, 7], 7));\n}\n", "5|logic-rust-return-in-loop|the loop returns on its first pass whichever way the `if` goes, so it never looks past the first item" },
        { "Search.scala", "object Search {\n  def contains(items: List[Int], wanted: Int): Boolean = {\n    for (item <- items) {\n      if (item == wanted) {\n        return true\n      } else {\n        return false\n      }\n    }\n    false\n  }\n\n  def main(args: Array[String]): Unit = {\n    println(contains(List(3, 5, 7), 7))\n  }\n}\n", "6|logic-scala-return-in-loop|the loop returns on its first pass whichever way the `if` goes, so it never looks past the first item" },
