        { "near.pl", "use strict;\nuse warnings;\n\nsub first_or_none {\n    my @items = @_;\n    foreach my $item (@items) {\n        if ($item < 0) {\n            return -1;\n        } else {\n            return $item;\n        }\n    }\n    return -1;\n}\n\nsub stops_at_first_negative {\n    my ($wanted, @items) = @_;\n    foreach my $item (@items) {\n        if ($item > 0) {\n            return 1 if $item == $wanted;\n        } else {\n            return 0;\n        }\n    }\n    return 0;\n}\n\nsub first_non_negative_is {\n    my ($wanted, @items) = @_;\n    foreach my $item (@items) {\n        if ($item == $wanted) {\n            return 1;\n        } elsif ($item < 0) {\n            next;\n        } else {\n            return 0;\n        }\n    }\n    return 0;\n}\n\nprint first_or_none(3, 5), \" \", stops_at_first_negative(5, 3, -1, 5), \" \", first_non_negative_is(5, 3, -1, 5), \"\\n\";\n" },
        { "near.ps1", "function Get-FirstOrNone($items) {\n    foreach ($item in $items) {\n        if ($item -lt 0) {\n            return -1\n        } else {\n            return $item\n        }\n    }\n    return -1\n}\n\nfunction Test-StopsAtFirstNegative($items, $wanted) {\n    foreach ($item in $items) {\n        if ($item -gt 0) {\n            if ($item -eq $wanted) {\n                return $true\n            }\n        } else {\n            return $false\n        }\n    }\n    return $false\n}\n\nfunction Test-FirstNonNegativeIs($items, $wanted) {\n    foreach ($item in $items) {\n        if ($item -eq $wanted) {\n            return $true\n        } elseif ($item -lt 0) {\n            continue\n        } else {\n            return $false\n        }\n    }\n    return $false\n}\n\nfunction Get-EachAnswer($items, $wanted) {\n    $items | ForEach-Object {\n        if ($_ -eq $wanted) {\n            return $true\n        } else {\n            return $false\n        }\n    }\n}\n\nGet-FirstOrNone @(3, 5)\nTest-StopsAtFirstNegative @(3, -1, 5) 5\nTest-FirstNonNegativeIs @(3, -1, 5) 5\nGet-EachAnswer @(3, 5) 5\n" },
        { "near.rb", "def first_or_none(items)\n  items.each do |item|\n    if item < 0\n      return -1\n    else\n      return item\n    end\n  end\n  -1\nend\n\ndef stops_at_first_negative(items, wanted)\n  items.each do |item|\n    if item > 0\n      return true if item == wanted\n    else\n      return false\n    end\n  end\n  false\nend\n\ndef first_non_negative_is(items, wanted)\n  items.each do |item|\n    if item == wanted\n      return true\n    elsif item < 0\n      next\n    else\n      return false\n    end\n  end\n  false\nend\n\nputs first_or_none([3, 5]), stops_at_first_negative([3, -1, 5], 5), first_non_negative_is([3, -1, 5], 5)\n" },
        { "near.rs", "fn first_or_none(items: &[i32]) -> i32 {\n    for item in items {\n        if *item < 0 {\n            return -1;\n        } else {\n            return *item;\n        }\n    }\n    -1\n}\n\nfn stops_at_first_negative(items: &[i32], wanted: i32) -> bool {\n    for item in items {\n        if *item > 0 {\n            if *item == wanted {\n                return true;\n            }\n        } else {\n            return false;\n        }\n    }\n    false\n}\n\nfn first_non_negative_is(items: &[i32], wanted: i32) -> bool {\n    for item in items {\n        if *item == wanted {\n            return true;\n        } else if *item < 0 {\n            continue;\n        } else {\n            return false;\n        }\n    }\n    false\n}\n\nfn main() {\n    println!(\"{} {} {}\", first_or_none(&[3, 5]), stops_at_first_negative(&[3, -1, 5], 5), first_non_negative_is(&[3, -1, 5], 5));\n}\n" },
        { "Near.scala", "object Near {\n  def firstOrNone(items: List[Int]): Int = {\n    for (item <- items) {\n      if (item < 0) {\n        return -1\n      } else {\n        return item\n      }\n    }\n    -1\n  }\n\n  def stopsAtFirstNegative(items: List[Int], wanted: Int): Boolean = {\n    for (item <- items) {\n      if (item > 0) {\n        if (item == wanted) {\n          return true\n        }\n      } else {\n        return false\n      }\n    }\n    false\n  }\n\n  def firstNonNegativeIs(items: List[Int], wanted: Int): Boolean = {\n    for (item <- items) {\n      if (item == wanted) {\n        return true\n      } else if (item < 0) {\n        println(\"skipped \" + item)\n      } else {\n        return false\n      }\n    }\n    false\n  }\n\n  def main(args: Array[String]): Unit = {\n    println(s\"${firstOrNone(List(3, 5))} ${stopsAtFirstNegative(List(3, -1, 5), 5)} ${firstNonNegativeIs(List(3, -1, 5), 5)}\")\n  }\n}\n" },
    };

    /// <summary>Code runs after the first loop, and the second is inside another loop: moving either return would change what runs.</summary>
    private const string OtherCodeAfterTheLoop = "local function contains(items, wanted)\n  for _, item in ipairs(items) do\n    if item == wanted then\n      return true\n    else\n      return false\n    end\n  end\n  print(\"no items\")\n  return false\nend\n\nlocal function in_any_row(rows, wanted)\n  for _, row in ipairs(rows) do\n    for _, item in ipairs(row) do\n      if item == wanted then\n        return true\n      else\n        return false\n      end\n    end\n  end\n  return false\nend\n\nprint(contains({3, 5, 7}, 7), in_any_row({{3, 5}, {7}}, 7))\n";

    [Theory]
    [MemberData(nameof(Found))]
    public void ALoopThatReturnsWhicheverWayTheIfGoesIsFound(string fileName, string code, string said)
    {
        Assert.Equal([said], Scanned(fileName, code).Select(finding => $"{finding.Line}|{finding.PatternId}|{finding.Message}"));
    }

    [Theory]
    [MemberData(nameof(Changed))]
    public void TheChangeLooksAtEveryItemBeforeSayingNo(string fileName, string code, string changed)
    {
        var finding = Assert.Single(Scanned(fileName, code));

        Assert.NotNull(finding.Fix);
        Assert.Equal(changed, string.Join("\n", finding.Fix.ApplyTo(Source(fileName, code)) ?? []));
    }

    [Fact]
    public void NoChangeIsOfferedWhereMovingTheReturnWouldChangeWhatRuns()
    {
        var findings = Scanned("other.lua", OtherCodeAfterTheLoop);

        Assert.Equal([5, 18], findings.Select(finding => finding.Line));
        Assert.All(findings, finding => Assert.Null(finding.Fix));
    }

    [Theory]
    [MemberData(nameof(NearMisses))]
    public void TheItemItselfANestedReturnAndAChainThatSkipsItemsAreLeftAlone(string fileName, string code)
    {
        Assert.Empty(Scanned(fileName, code));
    }
}
